(() => { const app = window.__CITY_APP, C = window.CITY, a = C.worldFromLatLon(43.683, -79.425), b = C.worldFromLatLon(43.6845, -79.416);
app.teleportTo(b.x, b.z, 0); app.cameraSystem.cinema = () => ({ pos: [a.x, 70, a.z], look: [b.x, 0, b.z], fov: 50 });
setTimeout(() => { const by = {}; for (const c of app.streetcars.cars) { const s = c.sections[2]; if (Math.hypot(s.x - b.x, s.z - b.z) > 400) continue; const k = c.route ? c.route.sign.join(' / ') : 'none'; by[k] = (by[k] || 0) + 1; }
console.log('[ttc-shot] e01-st-clair-bathurst: 512 St Clair at Bathurst; streetcars within 400 m: ' + JSON.stringify(by)); }, 8000); })()

